import { useEffect, useState } from "react";
import { BadgeCheck, Clock3, Megaphone, Upload, WalletCards } from "lucide-react";
import { createPromotion, getMyPromotions } from "../../api/localPromotionApi";
import { uploadFile } from "../../api/uploadApi";

const packages = [
  { code: "SHOP_FEATURE_7D", name: "Featured shop · 7 days", amount: 99, detail: "Highlight your business in local discovery." },
  { code: "OFFER_FEATURE_7D", name: "Featured offer · 7 days", amount: 149, detail: "Give one offer extra visibility." },
  { code: "HOMEPAGE_7D", name: "Homepage feature · 7 days", amount: 299, detail: "Request a homepage promotion placement." },
  { code: "LOCAL_MONTH_30D", name: "Local growth · 30 days", amount: 599, detail: "A 30-day local visibility package." },
];
const unwrap = r => r?.data?.data ?? r?.data ?? [];
const money = v => new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", maximumFractionDigits: 0 }).format(v || 0);
export default function LocalPromotions() {
  const [items, setItems] = useState([]); const [packageCode, setPackageCode] = useState(packages[0].code); const [targetType, setTargetType] = useState("SHOP"); const [targetId, setTargetId] = useState(""); const [proof, setProof] = useState(""); const [uploading, setUploading] = useState(false); const [saving, setSaving] = useState(false); const [message, setMessage] = useState(""); const [error, setError] = useState("");
  const load = () => getMyPromotions().then(r => setItems(unwrap(r))).catch(() => setItems([]));
  useEffect(() => { load(); }, []);
  const upload = async e => { const file=e.target.files?.[0]; if(!file) return; setError("");setMessage("");setUploading(true);try{const r=await uploadFile(file,"local-promotion-proof");const data=unwrap(r);setProof(data.secureUrl||data.url||"");if(!(data.secureUrl||data.url))throw new Error("Upload response did not include a file URL.");setMessage("Payment proof uploaded successfully.");}catch(err){setError(err.response?.data?.message||err.message||"Upload failed. Check Cloudinary configuration.");}finally{setUploading(false);e.target.value="";} };
  const submit = async e => { e.preventDefault();setError("");setMessage("");if(!proof){setError("Please upload your payment proof first.");return;}setSaving(true);try{await createPromotion({packageCode,targetType,targetId:targetId.trim()||null,paymentProofUrl:proof});setMessage("Request submitted. The campaign will start only after an administrator verifies the payment.");setProof("");setTargetId("");await load();}catch(err){setError(err.response?.data?.message||err.response?.data?.error||"Could not submit the promotion request.");}finally{setSaving(false);} };
  return <div className="page-shell"><div className="mb-6 rounded-3xl bg-gradient-to-r from-indigo-950 to-indigo-700 p-6 text-white sm:p-8"><div className="flex items-start gap-4"><div className="rounded-2xl bg-white/10 p-3"><Megaphone size={26}/></div><div><p className="text-xs font-bold tracking-[.18em] text-indigo-200">ASMJ LOCAL</p><h1 className="mt-1 text-2xl font-black sm:text-3xl">Promote your business</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-indigo-100">Choose a package, upload payment proof and submit it for review. Promotions go live after admin verification.</p></div></div></div>
    {message&&<div className="mb-4 rounded-xl border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-800">{message}</div>}{error&&<div className="mb-4 rounded-xl border border-red-200 bg-red-50 p-3 text-sm text-red-700">{error}</div>}
    <div className="grid gap-6 lg:grid-cols-[1fr_1.1fr]"><section><h2 className="mb-3 text-lg font-black">Choose your package</h2><div className="space-y-3">{packages.map(p=><button key={p.code} onClick={()=>setPackageCode(p.code)} className={`w-full rounded-2xl border p-4 text-left transition ${packageCode===p.code?"border-indigo-500 bg-indigo-50 ring-2 ring-indigo-100":"border-slate-200 bg-white hover:border-indigo-200"}`}><div className="flex items-start justify-between gap-3"><div><p className="font-extrabold">{p.name}</p><p className="mt-1 text-sm text-slate-500">{p.detail}</p></div><p className="whitespace-nowrap text-lg font-black text-indigo-700">{money(p.amount)}</p></div></button>)}</div></section>
    <form onSubmit={submit} className="card space-y-4 p-5 sm:p-6"><h2 className="text-lg font-black">Promotion request</h2><div><label className="label">What do you want to promote?</label><select className="input" value={targetType} onChange={e=>setTargetType(e.target.value)}><option value="SHOP">My business profile</option><option value="OFFER">An offer</option><option value="LISTING">A product or service listing</option></select></div><div><label className="label">Listing ID (optional)</label><input className="input" value={targetId} onChange={e=>setTargetId(e.target.value)} placeholder="Only if promoting a specific listing"/><p className="mt-1 text-xs text-slate-500">For shop profile promotion, leave this blank.</p></div><div className="rounded-xl border border-dashed border-slate-300 p-4"><label className="mb-2 block text-sm font-bold">Payment proof (image or PDF)</label><label className="flex cursor-pointer items-center justify-center gap-2 rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm font-bold hover:bg-slate-100"><Upload size={16}/>{uploading?"Uploading…":proof?"Upload a different proof":"Choose proof file"}<input type="file" accept="image/*,.pdf" className="hidden" disabled={uploading} onChange={upload}/></label>{proof&&<p className="mt-2 break-all text-xs text-emerald-700">Proof attached: {proof}</p>}<p className="mt-2 text-xs leading-5 text-slate-500">Use the official payment details shared by ASMJ. Keep your transaction reference for follow-up. Do not upload unrelated documents.</p></div><button disabled={saving||uploading} className="btn-primary w-full disabled:opacity-60">{saving?"Submitting…":"Submit for verification"}</button><p className="text-xs leading-5 text-slate-500">Displayed package prices are the pilot rates. A request does not activate a campaign until an admin approves the proof.</p></form></div>
    <section className="mt-8"><h2 className="mb-3 text-lg font-black">Your promotion requests</h2>{items.length?<div className="grid gap-3 md:grid-cols-2">{items.map(p=><article key={p.id} className="card p-4"><div className="flex items-start justify-between gap-3"><div><p className="font-bold">{p.packageName}</p><p className="mt-1 text-sm text-slate-500">{money(p.amountInr)} · {p.durationDays} days</p></div><span className={`rounded-full px-2.5 py-1 text-xs font-bold ${p.status==="ACTIVE"?"bg-emerald-100 text-emerald-700":p.status==="REJECTED"?"bg-red-100 text-red-700":"bg-amber-100 text-amber-800"}`}>{p.status?.replaceAll("_"," ")}</span></div><div className="mt-4 flex flex-wrap gap-4 text-xs text-slate-500"><span className="flex items-center gap-1"><Clock3 size={14}/> {p.endsAt?`Ends ${new Date(p.endsAt).toLocaleDateString()}:`:"Awaiting review"}</span><span className="flex items-center gap-1"><BadgeCheck size={14}/> {p.views||0} views · {p.clicks||0} clicks</span></div>{p.adminNote&&<p className="mt-3 rounded-lg bg-slate-50 p-2 text-sm text-slate-600">Admin note: {p.adminNote}</p>}</article>)}</div>:<div className="card p-8 text-center text-sm text-slate-500"><WalletCards className="mx-auto mb-2" size={24}/>No promotion requests yet.</div>}</section>
  </div>;
}
